HTMLReactVueSvelte <p>Inline HTML uses a JSON string in the <code>config</code> attribute:</p> <pre><code>&lt;triiiceratops-viewer
  manifest-id="https://example.org/iiif/manifest.json"
  config='{"toolbar": {"side": "right"}, "gallery": {"open": true}}'
&gt;&lt;/triiiceratops-viewer&gt;
</code></pre> <p>From JavaScript, prefer assigning a plain object to the <code>config</code> property:</p> <pre><code>const viewer = document.querySelector('triiiceratops-viewer');
viewer.config = {
  toolbar: { side: 'left' },
  gallery: { dockPosition: 'right' }
};
</code></pre> <pre><code>import { TriiiceratopsViewer } from 'triiiceratops/react';
import type { ViewerConfig } from 'triiiceratops/react';

// Hoisted (or `useMemo`d) so a parent re-render does not re-apply it.
const config: ViewerConfig = {
    toolbar: { side: 'left' },
    gallery: { dockPosition: 'right' },
};

export function Reader() {
    return (
        &lt;TriiiceratopsViewer
            manifestId="https://example.org/iiif/manifest.json"
            config={config}
            style={{ display: 'block', height: '600px' }}
        /&gt;
    );
}
</code></pre> <pre><code>&lt;script setup lang="ts"&gt;
import { shallowRef } from 'vue';
import { TriiiceratopsViewer, type ViewerConfig } from 'triiiceratops/vue';

// shallowRef, not ref: the wrapper receives this exact object.
const config = shallowRef&lt;ViewerConfig&gt;({
    toolbar: { side: 'left' },
    gallery: { dockPosition: 'right' },
});
&lt;/script&gt;

&lt;template&gt;
    &lt;TriiiceratopsViewer
        manifest-id="https://example.org/iiif/manifest.json"
        :config="config"
        style="display: block; height: 600px"
    /&gt;
&lt;/template&gt;
</code></pre> <pre><code>&lt;script&gt;
  import { TriiiceratopsViewer } from 'triiiceratops/svelte';
  import 'triiiceratops/style.css';

  let config = $state({
    toolbar: { side: 'left' },
    gallery: { open: true }
  });
&lt;/script&gt;

&lt;TriiiceratopsViewer {config} manifestId="https://example.org/iiif/manifest.json" /&gt;
</code></pre> <p>Driving the element directly: if you use <code>setAttribute('config', …)</code>, stringify the object yourself, and assign a new <code>config</code> object for updates.</p>

HTMLReactVueSvelte <p>As an attribute, JSON-encoded:</p> <pre><code>&lt;triiiceratops-viewer
    manifest-id="..."
    theme="light"
    theme-config='{"primary":"#ff0000","panelBg":"#fafafa","radiusBox":"0px"}'
&gt;&lt;/triiiceratops-viewer&gt;
</code></pre> <p>Or as a property, from JavaScript:</p> <pre><code>&lt;triiiceratops-viewer manifest-id="..."&gt;&lt;/triiiceratops-viewer&gt;

&lt;script&gt;
    const viewer = document.querySelector('triiiceratops-viewer');
    viewer.theme = 'light';
    viewer.themeConfig = {
        primary: '#3b82f6',
        toolbarBg: '#1f2937',
        panelBg: '#f3f4f6',
        metadataPanelBg: '#ffffff',
        content: '#1f2937',
        radiusBox: '0.75rem',
        border: '2px',
    };
&lt;/script&gt;
</code></pre> <p>Assign a new <code>themeConfig</code> object when updating from JavaScript. Mutating a nested property on the existing object does not notify the custom element.</p> <pre><code>import { TriiiceratopsViewer } from 'triiiceratops/react';
import type { ThemeConfig } from 'triiiceratops';

// Defined outside the component (or memoized) so the wrapper's shallow
// equality check sees a stable value and never re-applies it.
const customTheme: ThemeConfig = {
    primary: '#0ea5e9',
    panelBg: '#0f172a',
    radiusBox: '1rem',
};

export function Reader() {
    return (
        &lt;TriiiceratopsViewer
            manifestId="..."
            theme="light"
            themeConfig={customTheme}
        /&gt;
    );
}
</code></pre> <pre><code>&lt;script setup lang="ts"&gt;
import { shallowRef } from 'vue';
import { TriiiceratopsViewer } from 'triiiceratops/vue';
import type { ThemeConfig } from 'triiiceratops';

const customTheme = shallowRef&lt;ThemeConfig&gt;({
    primary: '#0ea5e9',
    panelBg: '#0f172a',
    radiusBox: '1rem',
});
&lt;/script&gt;

&lt;template&gt;
    &lt;TriiiceratopsViewer
        manifest-id="..."
        theme="light"
        :theme-config="customTheme"
    /&gt;
&lt;/template&gt;
</code></pre> <pre><code>&lt;script lang="ts"&gt;
    import { TriiiceratopsViewer } from 'triiiceratops/svelte';
    import 'triiiceratops/style.css';
    import type { ThemeConfig } from 'triiiceratops';

    const customTheme: ThemeConfig = {
        primary: '#0ea5e9',
        panelBg: '#0f172a',
        radiusBox: '1rem',
    };
&lt;/script&gt;

&lt;TriiiceratopsViewer manifestId="..." theme="light" themeConfig={customTheme} /&gt;
</code></pre>
